def run_loop(decide, tools, max_steps):
    history = []
    for step in range(1, max_steps + 1):
        d = decide(history)
        if 'final' in d:
            return {'status': 'done', 'answer': d['final'], 'steps': step}
        if d['tool'] not in tools:
            return {'status': 'unknown_tool', 'steps': step}
        history.append(tools[d['tool']](**d['args']))
    return {'status': 'step_limit', 'steps': max_steps}

